<template><view class="page"><view class="nav"><view class="back" @click="back">‹ {{ tr('Back') }}</view><text>{{ tr('Help & Feedback') }}</text><view class="nav-space" /></view>
  <view class="hero"><view class="hero-icon">?</view><text class="hero-title">{{ tr('How can we help?') }}</text><text class="hero-sub">{{ tr('A simple guide to your device and measurements') }}</text></view>
